baseCss:
.aha-slider{
  container:aha-slider / inline-size;
  position:relative;isolation:isolate;overflow:hidden;
  font-family:var(--aha-font-product);
  background:var(--aha-white);
  color:var(--aha-text-default);
}
.aha-slider *{box-sizing:border-box}
:where(.aha-slider) :is(h2,h3,p,figure,ul){margin:0;padding:0}
:where(.aha-slider) ul{list-style:none}
.aha-slider__inner{
  display:flex;flex-direction:column;gap:var(--aha-space-64);
  width:100%;max-width:1280px;margin:0 auto;
  --aha-web-gutter:var(--aha-space-64);padding:var(--aha-space-96) var(--aha-web-gutter);
}
.aha-slider__header{display:flex;flex-direction:column;align-items:center;max-width:720px;margin:0 auto;text-align:center}
.aha-slider__eyebrow{
  margin-bottom:var(--aha-space-12);
  font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-subheadings);text-transform:uppercase;
  color:var(--aha-color-primary);
}
.aha-slider__title{
  margin-bottom:var(--aha-space-16);
  font-size:var(--aha-size-h2);font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-text-default);
}
.aha-slider__lead{
  max-width:44ch;
  font-size:clamp(var(--aha-size-l),1.4vw,var(--aha-size-xl));
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-slider__body{display:flex;flex-direction:column;gap:var(--aha-space-32)}
.aha-slider__stage{position:relative}
.aha-slider__stage:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-slider__arrow{position:absolute;z-index:2;top:50%;transform:translateY(-50%)}
.aha-slider__arrow--prev{left:var(--aha-slider-arrow-inset,var(--aha-space-16))}
.aha-slider__arrow--next{right:var(--aha-slider-arrow-inset,var(--aha-space-16))}
.aha-slider:not(.aha-slider--armed) :is(.aha-slider__arrow,.aha-slider__dots){display:none}
.aha-slider__dots{display:flex;flex-wrap:wrap;justify-content:center;gap:var(--aha-space-4)}
.aha-slider__dot{
  --aha-slider-dot:var(--aha-icon-muted);
  display:inline-flex;align-items:center;justify-content:center;
  min-width:var(--aha-space-24);min-height:var(--aha-space-24);padding:0 var(--aha-space-2);
  border:0;background:none;cursor:pointer;
}
.aha-slider__dot[hidden]{display:none}
.aha-slider__dot::before{
  content:"";display:block;width:var(--aha-space-16);height:var(--aha-space-4);
  border-radius:var(--aha-radius-xs);background:var(--aha-slider-dot);
  transition:width var(--aha-motion-mid) var(--aha-ease-in-out),background var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-slider__dot:hover{--aha-slider-dot:var(--aha-vivid-pink-dark)}
.aha-slider__dot[aria-current="true"]{--aha-slider-dot:var(--aha-color-primary)}
.aha-slider__dot[aria-current="true"]::before{width:var(--aha-space-28)}
.aha-slider__dot:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:0;border-radius:var(--aha-radius-xs)}
.aha-slider__cta{display:flex;flex-wrap:wrap;justify-content:center;gap:var(--aha-space-12);margin-top:var(--aha-space-48)}
.aha-slider__visually-hidden{
  position:absolute;width:1px;height:1px;margin:-1px;padding:0;
  overflow:hidden;clip-path:inset(50%);white-space:nowrap;
}
@media (prefers-reduced-motion:reduce){
  .aha-slider__dot::before{transition:none}
}
@container aha-slider (max-width:991px){
  .aha-slider__title{font-size:var(--aha-size-h3)}
}
@container aha-slider (max-width:767px){
  .aha-slider__inner{--aha-web-gutter:var(--aha-space-24);padding:var(--aha-space-48) var(--aha-web-gutter);gap:var(--aha-space-48)}
}
@container aha-slider (max-width:479px){
  .aha-slider__inner{--aha-web-gutter:var(--aha-space-16);padding:var(--aha-space-32) var(--aha-web-gutter);gap:var(--aha-space-32)}
  .aha-slider__title{font-size:var(--aha-size-h4)}
  .aha-slider__cta{margin-top:var(--aha-space-32)}
}

layouts.css:
.aha-slider--zoom{--aha-slider-media-height:1.3333}
.aha-slider--portrait{--aha-slider-media-height:1.3333}
.aha-slider--square{--aha-slider-media-height:1}
.aha-slider--landscape{--aha-slider-media-height:.75}
.aha-slider--wide{--aha-slider-media-height:.5625}
.aha-slider--landscape .aha-slider__stage--zoom{--aha-slider-zoom-share:40}
.aha-slider--wide .aha-slider__stage--zoom{--aha-slider-zoom-share:56}
.aha-slider__stage--zoom{
  --aha-slider-zoom-share:28;
  container:aha-slider-zoom / inline-size;
  width:100cqi;margin-inline:calc(50% - 50cqi);
  overflow:hidden;
  --aha-slider-arrow-inset:var(--aha-web-gutter);
}
.aha-slider__stage--zoom .aha-slider__arrow{top:calc(min(calc(var(--aha-slider-zoom-share) * 1cqi),calc(1280px * var(--aha-slider-zoom-share) / 100)) * var(--aha-slider-media-height) / 2)}
.aha-slider__zoom-track{
  display:flex;gap:var(--aha-space-24);
  padding-inline:var(--aha-web-gutter);
  overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none; /* ds-lint-allow: overflow-x-scroll (no-script fallback: the slides stay reachable as a swipe row until the slider script arms the stage) */
}
.aha-slider__zoom-track::-webkit-scrollbar{display:none}
.aha-slider__zoom-slide{
  --aha-slider-zoom-card:min(calc(var(--aha-slider-zoom-share) * 1cqi),calc(1280px * var(--aha-slider-zoom-share) / 100));
  flex:none;width:var(--aha-slider-zoom-card);min-width:0;scroll-snap-align:center;
}
.aha-slider--armed .aha-slider__zoom-track{
  display:grid;justify-items:center;align-items:start;
  padding-inline:0;overflow:visible;
  touch-action:pan-y;user-select:none;cursor:grab;
}
.aha-slider--armed .aha-slider__zoom-slide{
  grid-area:1 / 1;
  transform:translateX(calc(var(--aha-slider-position,0) * (var(--aha-slider-zoom-card) + var(--aha-space-24)))) scale(var(--aha-slider-scale,1));
  transform-origin:center top;
  transition:transform var(--aha-motion-viz-enter) var(--aha-ease-out);
}
.aha-slider--armed .aha-slider__zoom-slide:not([aria-hidden="true"]){z-index:1}
.aha-slider--dragging .aha-slider__zoom-track{cursor:grabbing}
.aha-slider--dragging .aha-slider__zoom-slide,
.aha-slider__zoom-slide.aha-slider__zoom-slide--jump{transition:none}
.aha-slider__zoom-card{display:flex;flex-direction:column;gap:var(--aha-space-16);text-align:center}
.aha-slider__media{
  position:relative;width:100%;
  aspect-ratio:calc(1 / var(--aha-slider-media-height));overflow:hidden;
  border-radius:var(--aha-radius-marketing);
  background:var(--aha-bg-container-secondary);
}
.aha-slider__shot{display:block;width:100%;height:100%;object-fit:cover;-webkit-user-drag:none}
.aha-slider__caption{display:flex;flex-direction:column;gap:var(--aha-space-4)}
.aha-slider__caption-title{font-size:var(--aha-size-xl);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);color:var(--aha-text-default)}
.aha-slider__caption-text{font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
@media (prefers-reduced-motion:reduce){
  .aha-slider--armed .aha-slider__zoom-slide{transition:none}
}
@container aha-slider (max-width:991px){
  .aha-slider__stage--zoom{--aha-slider-zoom-share:40}
  .aha-slider--landscape .aha-slider__stage--zoom{--aha-slider-zoom-share:56}
  .aha-slider--wide .aha-slider__stage--zoom{--aha-slider-zoom-share:68}
}
@container aha-slider (max-width:767px){
  .aha-slider__stage--zoom{--aha-slider-zoom-share:56}
  .aha-slider--landscape .aha-slider__stage--zoom,.aha-slider--wide .aha-slider__stage--zoom{--aha-slider-zoom-share:68}
  .aha-slider__zoom-track{gap:var(--aha-space-16)}
  .aha-slider--armed .aha-slider__zoom-slide{transform:translateX(calc(var(--aha-slider-position,0) * (var(--aha-slider-zoom-card) + var(--aha-space-16)))) scale(var(--aha-slider-scale,1))}
}
@container aha-slider (max-width:479px){
  .aha-slider__stage--zoom{--aha-slider-zoom-share:68}
  .aha-slider__caption-title{font-size:var(--aha-size-l)}
}

.aha-slider--card{--aha-slider-media-height:.75}
.aha-slider--portrait{--aha-slider-media-height:1.3333}
.aha-slider--square{--aha-slider-media-height:1}
.aha-slider--landscape{--aha-slider-media-height:.75}
.aha-slider--wide{--aha-slider-media-height:.5625}
.aha-slider__stage--card{
  container:aha-slider-card / inline-size;
  --aha-slider-card-gap:var(--aha-space-24);
  --aha-slider-per-view:3;
}
.aha-slider__card-track{
  --aha-slider-card-width:calc((100cqi - (var(--aha-slider-per-view) - 1) * var(--aha-slider-card-gap)) / var(--aha-slider-per-view));
  display:flex;gap:var(--aha-slider-card-gap);
  overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none; /* ds-lint-allow: overflow-x-scroll (swipeable slider track, moved by the arrow buttons, the dots, arrow keys and drag) */
}
.aha-slider__card-track::-webkit-scrollbar{display:none}
.aha-slider__card-track:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-slider--dragging .aha-slider__card-track{scroll-snap-type:none;cursor:grabbing;user-select:none}
.aha-slider__card-slide{flex:none;width:var(--aha-slider-card-width);min-width:0;scroll-snap-align:start}
.aha-slider__card{position:relative;display:flex;flex-direction:column;gap:var(--aha-space-8);text-align:left}
.aha-slider__card-media{margin-bottom:var(--aha-space-12);aspect-ratio:calc(1 / var(--aha-slider-media-height));overflow:hidden;border-radius:var(--aha-radius-marketing);background:var(--aha-bg-container-secondary)}
.aha-slider__card-image{display:block;width:100%;height:100%;object-fit:cover;-webkit-user-drag:none;transition:transform var(--aha-motion-slow) var(--aha-ease-out)}
.aha-slider__card:hover .aha-slider__card-image{transform:scale(1.04)}
.aha-slider__meta{font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-text-tertiary)}
.aha-slider__card-title{font-size:var(--aha-size-xl);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);color:var(--aha-text-default)}
.aha-slider__link{color:inherit;text-decoration:none}
.aha-slider__link::after{content:"";position:absolute;inset:0}
.aha-slider__link:focus-visible{outline:none}
.aha-slider__card:hover .aha-slider__link{color:var(--aha-text-link-hover)}
.aha-slider__card:has(.aha-slider__link:focus-visible){outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2);border-radius:var(--aha-radius-marketing)}
.aha-slider__stage--card .aha-slider__arrow{top:calc(var(--aha-slider-card-width-outer) * var(--aha-slider-media-height) / 2)}
.aha-slider__stage--card{--aha-slider-card-width-outer:calc((100cqi - (var(--aha-slider-per-view) - 1) * var(--aha-slider-card-gap)) / var(--aha-slider-per-view))}
@media (prefers-reduced-motion:reduce){
  .aha-slider__card-image{transition:none}
  .aha-slider__card:hover .aha-slider__card-image{transform:none}
}
@container aha-slider (max-width:991px){
  .aha-slider__stage--card{--aha-slider-per-view:2}
}
@container aha-slider (max-width:767px){
  .aha-slider__stage--card{--aha-slider-card-gap:var(--aha-space-16);--aha-slider-per-view:1}
}
